import type { Schemas } from '@/lib/api/client';
import { toSnapshotView } from './connection';
import canonical from './canonical-snapshots.json';
import { lifecycleStyles } from './lifecycle';
import { actionLabels, timeLabel, type SnapshotView } from './view';

// Generated by `make gen-api` (A's app.export_fixtures). Never hand-edit canonical-snapshots.json.
export const previewFrames = Object.entries(canonical)
  .filter(([key]) => key.startsWith('t'))
  .map(([, value]) => toSnapshotView(value as unknown as Schemas['SessionSnapshot']))
  .sort((a, b) => a.timeS - b.timeS);

export function previewAt(timeS: number): SnapshotView {
  // Select complete authored snapshots; never derive lifecycle or route decisions.
  // The displayed clock stays at the snapshot time because there is no offline engine.
  return [...previewFrames].reverse().find((frame) => frame.timeS <= timeS) ?? previewFrames[0];
}

/** One chapter per generated frame, labelled only from that frame's server values. */
export function previewChapters(frames: SnapshotView[] = previewFrames) {
  return frames.map((frame) => {
    const hazard = frame.hazards[0];
    return {
      timeS: frame.timeS,
      label: [
        timeLabel(frame.timeS),
        hazard ? lifecycleStyles[hazard.state].label : 'No reports',
        frame.decision ? actionLabels[frame.decision.action] : 'No recommendation',
      ].join(' · '),
    };
  });
}
